+/**
+ * Fetch the public permalink for a media ID via the Instagram Graph API.
+ */
+async function fetchPermalink(
+  mediaId: string,
+  env: Env
+): Promise<string | null> {
+  try {
+    const response = await fetch(
+      `https://graph.instagram.com/v22.0/${mediaId}?fields=permalink&access_token=${env.PAGE_ACCESS_TOKEN}`
+    );
+    if (!response.ok) {
+      const error = await response.text();
+      console.error(`Failed to fetch permalink: ${response.status} ${error}`);
+      return null;
+    }
+    const data: { permalink?: string } = await response.json();
+    return data.permalink ?? null;
+  } catch (err) {
+    console.error(`Error fetching permalink: ${err}`);
+    return null;
+  }
